<template><view class="page"><text class="title">帮助与反馈</text><view class="card"><view v-for="q in faqs" :key="q.q" class="faq" @tap="q.open=!q.open"><view class="head"><text class="q">{{q.q}}</text><text>⌄</text></view><text v-if="q.open" class="a">{{q.a}}</text></view></view><text class="label">意见反馈</text><textarea v-model="feedback" class="textarea" placeholder="告诉我们哪里不好用，或希望增加什么功能"/><button class="save" @tap="submit">提交反馈</button></view></template><script>export default{data(){return{feedback:'',faqs:[{q:'老人端怎么使用？',a:'从首页进入老人端即可体验大字、少操作的照护页面。',open:false},{q:'如何添加家庭成员？',a:'进入“我的-家庭成员”，点击邀请家庭成员。',open:false},{q:'提醒为什么没有真实推送？',a:'当前版本仅完成前端交互，真实推送需要后端与系统通知能力接入。',open:false}]}},methods:{submit(){if(!this.feedback.trim())return uni.showToast({title:'请先填写反馈',icon:'none'});uni.setStorageSync('feedback_demo',this.feedback);this.feedback='';uni.showToast({title:'感谢反馈',icon:'success'})}}}</script><style scoped>.page{min-height:100vh;padding:30rpx;background:#f6f7f3}.title{display:block;font-size:40rpx;font-weight:900;color:#2d4338;margin-bottom:24rpx}.card{padding:0 24rpx;background:#fff;border-radius:28rpx}.faq{padding:24rpx 0;border-bottom:1rpx solid #edf0ec}.head{display:flex;justify-content:space-between}.q{font-size:25rpx;font-weight:800}.a{display:block;margin-top:12rpx;color:#78847d;font-size:21rpx;line-height:1.7}.label{display:block;margin:30rpx 0 12rpx;font-size:25rpx;font-weight:800}.textarea{width:100%;height:220rpx;box-sizing:border-box;padding:22rpx;background:#fff;border-radius:24rpx}.save{margin-top:22rpx;background:#326a53;color:#fff;border-radius:20rpx}</style>